# Repairs the installed RUET Downloader using bundled, corrected helper files.
$ErrorActionPreference = 'Stop'
try {
    $listener = Get-NetTCPConnection -LocalPort 8765 -State Listen -ErrorAction SilentlyContinue
    if ($listener) { throw 'Close all RUET Downloader windows first, then run this repair again. An existing server is still using port 8765.' }
    $installDir = Join-Path $env:LOCALAPPDATA 'RUET Downloader'
    New-Item -ItemType Directory -Force -Path $installDir | Out-Null
    $files = @{
    'server.py' = ''
    'start.bat' = ''
    'launch-protocol.bat' = ''
    }
    foreach ($name in $files.Keys) {
        $target = Join-Path $installDir $name
        if (Test-Path -LiteralPath $target) { Copy-Item -LiteralPath $target -Destination ($target + '.before-repair') -Force }
        [IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($files[$name]))
    }
    [IO.File]::WriteAllText((Join-Path $installDir 'allowed-origin.txt'), 'https://becm.vercel.app', (New-Object Text.UTF8Encoding($false)))
    $protocolKey = 'HKCU:\Software\Classes\ruetdownloader'
    $commandKey = $protocolKey + '\shell\open\command'
    New-Item -Path $commandKey -Force | Out-Null
    New-ItemProperty -Path $protocolKey -Name 'URL Protocol' -Value '' -PropertyType String -Force | Out-Null
    Set-Item -Path $protocolKey -Value 'URL:RUET Downloader Protocol'
    $launcher = Join-Path $installDir 'launch-protocol.bat'
    Set-Item -Path $commandKey -Value ('"' + $launcher + '" "%1"')
    Start-Process -FilePath $launcher -ArgumentList 'ruetdownloader://start' -WindowStyle Hidden
    Write-Host 'Corrected helper installed. Waiting for startup...' -ForegroundColor Cyan
    $ready = $false
    for ($attempt = 0; $attempt -lt 60; $attempt++) {
        try {
            $response = Invoke-WebRequest -UseBasicParsing -Method Options -Uri 'http://127.0.0.1:8765/download' -Headers @{Origin='https://becm.vercel.app'} -TimeoutSec 2
            if ($response.StatusCode -eq 200 -and $response.Headers['Access-Control-Allow-Origin'] -eq 'https://becm.vercel.app') { $ready = $true; break }
        } catch { }
        Start-Sleep -Seconds 1
    }
    if (-not $ready) { throw 'Helper files updated, but startup did not pass the connection check. Open the RUET Downloader window and send its error text.' }
    Write-Host 'PASS: Local server accepts the website. Return to the website and try Download.' -ForegroundColor Green
} catch {
    Write-Host ('REPAIR ERROR: ' + $_.Exception.Message) -ForegroundColor Red
}
Read-Host 'Press Enter to close'
